#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <stdlib.h>
#include <stdio.h>
#include <errno.h>
#include <limits.h>
#include <string>
#include <vector>
#include <mutex>
#include <filesystem>

namespace fs = std::filesystem;

class SecureUploadHandler {
private:
    std::string upload_root_;
    std::string staging_dir_;
    std::mutex upload_mutex_;

    // Security: Validate filename contains no path traversal
    bool validate_filename(const std::string& name) {
        if (name.empty() || name.length() > 255) return false;
        if (name[0] == '.') return false;
        if (name.find('/') != std::string::npos) return false;
        if (name.find('\\') != std::string::npos) return false;
        if (name.find("\0") != std::string::npos) return false;
        // Only allow alphanumeric, dash, underscore, dot (not leading)
        for (char c : name) {
            if (!isalnum(c) && c != '-' && c != '_' && c != '.') return false;
        }
        return true;
    }

    // Security: Resolve and verify path stays within allowed root
    bool verify_path_within_root(const std::string& path, const std::string& root) {
        char resolved_path[PATH_MAX];
        char resolved_root[PATH_MAX];

        // Resolve the parent directory (file may not exist yet)
        std::string parent = fs::path(path).parent_path().string();
        if (!realpath(parent.c_str(), resolved_path)) return false;
        if (!realpath(root.c_str(), resolved_root)) return false;

        std::string rp(resolved_path);
        std::string rr(resolved_root);

        // Ensure resolved path starts with resolved root
        if (rp.length() < rr.length()) return false;
        if (rp.compare(0, rr.length(), rr) != 0) return false;
        if (rp.length() > rr.length() && rp[rr.length()] != '/') return false;

        return true;
    }

    // Security: Check that target path is not a symlink
    // This prevents symlink-based attacks where an attacker
    // replaces the target with a symlink to a sensitive file
    bool is_safe_target(const std::string& path) {
        struct stat st;
        // Use lstat to detect symlinks (doesn't follow them)
        if (lstat(path.c_str(), &st) == 0) {
            // File exists - check it's not a symlink
            if (S_ISLNK(st.st_mode)) {
                return false;  // Reject: symlink detected
            }
            // File exists and is not a symlink - safe to overwrite
            return true;
        }
        // File doesn't exist - safe to create
        // (ENOENT means path is available)
        if (errno == ENOENT) return true;
        // Other errors - reject for safety
        return false;
    }

    // Write data to staging area first (safe temporary location)
    std::string write_to_staging(const std::string& filename, 
                                  const std::vector<uint8_t>& data) {
        std::string staging_path = staging_dir_ + "/tmp_" + filename;

        int fd = open(staging_path.c_str(), 
                      O_WRONLY | O_CREAT | O_TRUNC | O_NOFOLLOW,
                      0644);
        if (fd < 0) return "";

        size_t written = 0;
        while (written < data.size()) {
            ssize_t ret = write(fd, data.data() + written, 
                               data.size() - written);
            if (ret < 0) {
                close(fd);
                unlink(staging_path.c_str());
                return "";
            }
            written += ret;
        }

        // Sync to disk before moving
        fsync(fd);
        close(fd);
        return staging_path;
    }

public:
    SecureUploadHandler(const std::string& root, const std::string& staging)
        : upload_root_(root), staging_dir_(staging) {
        // Ensure directories exist
        mkdir(upload_root_.c_str(), 0755);
        mkdir(staging_dir_.c_str(), 0700);
    }

    // Main upload entry point
    // Returns 0 on success, negative on error
    int handle_upload(const std::string& user_filename,
                      const std::vector<uint8_t>& file_data,
                      uid_t requesting_uid) {
        // Step 1: Validate filename format
        if (!validate_filename(user_filename)) {
            return -1;  // Invalid filename
        }

        // Step 2: Size limit (10MB)
        if (file_data.size() > 10 * 1024 * 1024) {
            return -2;  // Too large
        }

        // Step 3: Construct target path
        std::string target_path = upload_root_ + "/" + user_filename;

        // Step 4: Verify path stays within upload root
        if (!verify_path_within_root(target_path, upload_root_)) {
            return -3;  // Path traversal attempt
        }

        // Step 5: Write to staging area
        std::string staged = write_to_staging(user_filename, file_data);
        if (staged.empty()) {
            return -4;  // Staging write failed
        }

        // Step 6: Security check - verify target is not a symlink
        // This is our defense against symlink race attacks
        if (!is_safe_target(target_path)) {
            unlink(staged.c_str());
            return -5;  // Symlink detected at target
        }

        // Step 7: Atomically move staged file to target
        // rename() is atomic on the same filesystem
        if (rename(staged.c_str(), target_path.c_str()) != 0) {
            unlink(staged.c_str());
            return -6;  // Move failed
        }

        return 0;  // Success
    }
};

// Request handler that processes upload HTTP requests
int process_upload_request(SecureUploadHandler& handler,
                           const std::string& filename,
                           const std::vector<uint8_t>& body,
                           uid_t uid) {
    return handler.handle_upload(filename, body, uid);
}
